<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();require __DIR__.'/config/database.php';require_once __DIR__.'/date-widget.php';$bid=current_business_id();$view=$view??'parties';$notice='';$error='';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function q1($pdo,$sql,$a=[]){$q=$pdo->prepare($sql);$q->execute($a);return$q->fetchAll();}function scalar($pdo,$sql,$a=[]){$q=$pdo->prepare($sql);$q->execute($a);return(float)$q->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf((string)($_POST['csrf']??'')))$error='Session expired. Please try again.';else try{$a=$_POST['action']??'';
if($a==='party'){ $id=(int)($_POST['id']??0);$code=strtoupper(trim($_POST['party_code']??''));$name=trim($_POST['party_name']??'');if(!$code||!$name)throw new RuntimeException('Party code and name are required.');$v=[$code,$name,trim($_POST['phone']??'')?:null,trim($_POST['address']??'')?:null,trim($_POST['pan_vat']??'')?:null,(float)($_POST['opening_balance']??0)];if($id){$v[]=$id;$v[]=$bid;$pdo->prepare('UPDATE parties SET party_code=?,party_name=?,phone=?,address=?,pan_vat=?,opening_balance=?,is_active=1 WHERE id=? AND business_id=?')->execute($v);}else{$pdo->prepare('INSERT INTO parties(business_id,party_code,party_name,phone,address,pan_vat,opening_balance) VALUES(?,?,?,?,?,?,?)')->execute(array_merge([$bid],$v));}$notice='Party saved.';}
if($a==='payment'){ $pid=(int)$_POST['party_id'];$amt=(float)$_POST['amount'];if(!$pid||$amt<=0)throw new RuntimeException('Party and positive amount are required.');$pdo->prepare('INSERT INTO payments(business_id,party_id,payment_date,amount,mode,reference,bank_wallet,note) VALUES(?,?,?,?,?,?,?,?)')->execute([$bid,$pid,$_POST['payment_date'],$amt,$_POST['mode'],trim($_POST['reference']??'')?:null,trim($_POST['bank_wallet']??'')?:null,trim($_POST['note']??'')?:null]);$notice='Payment received.';}
if($a==='sale'){ $items=json_decode($_POST['items_json']??'[]',true);if(!is_array($items)||!$items)throw new RuntimeException('Add at least one item.');$pdo->beginTransaction();$sub=0;foreach($items as$i){$pid=(int)$i['product_id'];$qty=(float)$i['qty'];$rate=(float)$i['rate'];if($qty<=0||$rate<0)throw new RuntimeException('Invalid sale item.');$stock=scalar($pdo,"SELECT COALESCE((SELECT SUM(qty*units_per_unit) FROM purchases WHERE business_id=? AND product_id=?),0)-COALESCE((SELECT SUM(si.qty) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.status='posted' AND si.product_id=?),0)",[$bid,$pid,$bid,$pid]);if($qty>$stock)throw new RuntimeException('Insufficient stock for a selected product.');$sub+=$qty*$rate;}$disc=min($sub,max(0,(float)($_POST['discount']??0)));$tax=max(0,$sub-$disc);$vr=isset($_POST['vat_enabled'])?(float)($_POST['vat_rate']??13):0;$vat=$tax*$vr/100;$total=$tax+$vat;$paid=max(0,min($total,(float)($_POST['paid_amount']??0)));$due=$total-$paid;$party=(int)($_POST['party_id']??0)?:null;if($due>0&&!$party)throw new RuntimeException('A saved party is required when there is due amount.');$n=(int)scalar($pdo,"SELECT COALESCE(MAX(CAST(SUBSTRING(bill_no,4) AS UNSIGNED)),0)+1 FROM sales WHERE business_id=? AND bill_no LIKE 'MB-%'",[$bid]);$bill='MB-'.str_pad((string)$n,5,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO sales(business_id,bill_no,sale_date,party_id,customer_name,customer_phone,customer_address,customer_pan,payment_type,payment_reference,bank_wallet,discount,vat_enabled,vat_rate,vat_amount,paid_amount,due_amount,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,\'posted\')')->execute([$bid,$bill,$_POST['sale_date'],$party,trim($_POST['customer_name']??'')?:'Cash Customer',trim($_POST['customer_phone']??'')?:null,trim($_POST['customer_address']??'')?:null,trim($_POST['customer_pan']??'')?:null,$_POST['payment_type'],trim($_POST['payment_reference']??'')?:null,trim($_POST['bank_wallet']??'')?:null,$disc,$vr>0?1:0,$vr,$vat,$paid,$due]);$sid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,qty,rate) VALUES(?,?,?,?)');foreach($items as$i)$ins->execute([$sid,(int)$i['product_id'],(float)$i['qty'],(float)$i['rate']]);$pdo->commit();$notice="Sale saved: $bill";}
}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Operation failed.';}}
$parties=q1($pdo,"SELECT p.*,p.opening_balance+COALESCE((SELECT SUM(s.due_amount) FROM sales s WHERE s.business_id=? AND s.party_id=p.id AND s.status='posted'),0)-COALESCE((SELECT SUM(py.amount) FROM payments py WHERE py.business_id=? AND py.party_id=p.id),0) current_due FROM parties p WHERE p.business_id=? AND p.is_active=1 ORDER BY p.party_name",[$bid,$bid,$bid]);$products=q1($pdo,"SELECT p.*,COALESCE((SELECT SUM(qty*units_per_unit) FROM purchases WHERE business_id=? AND product_id=p.id),0)-COALESCE((SELECT SUM(si.qty) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.status='posted' AND si.product_id=p.id),0) stock FROM products p WHERE p.business_id=? AND p.is_active=1 ORDER BY p.product_name",[$bid,$bid,$bid]);$sales=q1($pdo,"SELECT s.*,COALESCE((SELECT SUM(qty*rate) FROM sale_items WHERE sale_id=s.id),0) subtotal FROM sales s WHERE s.business_id=? ORDER BY s.sale_date DESC,s.id DESC",[$bid]);
$nav=['Dashboard'=>'index.php','Products'=>'products.php','Suppliers'=>'suppliers.php','Purchase Entry'=>'purchases.php','Party / Customer'=>'parties.php','Sales & Billing'=>'sales.php','Sales Register'=>'sales-register.php','Sales Reports'=>'sales-reports.php','Stock / Inventory'=>'stock.php','Price Comparison'=>'price-comparison.php'];$titles=['parties'=>'Party / Customer','sales'=>'Sales & Billing','register'=>'Sales Register','reports'=>'Sales Reports','stock'=>'Stock / Inventory','compare'=>'Price Comparison'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($titles[$view])?> • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/mero-date.css"><style>.msg{padding:10px;border-radius:8px;margin-bottom:12px}.ok{background:#ecfdf3;color:#166534}.err{background:#fff0f0;color:#991b1b}.small{font-size:12px}.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid #ffffff30}.accountbar a{color:#fff}.scroll{overflow:auto}.right{text-align:right}</style></head><body><aside class="sidebar"><div class="brand">MeroKhata</div><div class="subbrand">Online Database</div><div class="nav"><?php foreach($nav as$n=>$u):?><button class="<?=$n===$titles[$view]?'active':''?>" onclick="location.href='<?=$u?>'"><?=h($n)?></button><?php endforeach;?></div><div class="accountbar"><?=h($_SESSION['name']??'User')?> · <?=h(ucfirst($_SESSION['role']??''))?><br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1><?=h($titles[$view])?></h1><div class="muted">MeroKhata • Online</div></div><section class="panel active"><?php if($notice):?><div class="msg ok"><?=h($notice)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=h($error)?></div><?php endif;?>
<?php if($view==='parties'):?><div class="box"><h3>Add Party / Customer</h3><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="party"><div class="grid"><label>Party Code<input name="party_code" required placeholder="PTY-002"></label><label>Name<input name="party_name" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><label>PAN/VAT<input name="pan_vat"></label><label>Opening Due<input type="number" step=".01" name="opening_balance" value="0"></label></div><div class="actions"><button class="primary">Save Party</button></div></form></div><div class="box"><h3>Receive Payment</h3><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="payment"><div class="grid"><label>Date<?=mk_date_widget('payment_date','','BS')?></label><label>Party<select name="party_id" required><option value="">Select</option><?php foreach($parties as$p):?><option value="<?=$p['id']?>"><?=h($p['party_code'].' - '.$p['party_name'])?></option><?php endforeach;?></select></label><label>Amount<input type="number" step=".01" min=".01" name="amount" required></label><label>Mode<select name="mode"><option>Cash</option><option>Online</option><option>Cheque</option></select></label><label>Reference<input name="reference"></label><label>Bank / Wallet<input name="bank_wallet"></label><label>Note<input name="note"></label></div><div class="actions"><button class="primary">Receive Payment</button></div></form></div><div class="box scroll"><h3>Party Ledger Summary</h3><table><thead><tr><th>Code</th><th>Name</th><th>Phone</th><th>Address</th><th>Opening Due</th><th>Current Due</th></tr></thead><tbody><?php foreach($parties as$p):?><tr><td><?=h($p['party_code'])?></td><td><?=h($p['party_name'])?></td><td><?=h($p['phone'])?></td><td><?=h($p['address'])?></td><td>Rs. <?=number_format((float)$p['opening_balance'],2)?></td><td><b>Rs. <?=number_format((float)$p['current_due'],2)?></b></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($view==='sales'):?><div class="box"><h3>New Bill</h3><form method="post" id="saleForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="sale"><input type="hidden" name="items_json" id="itemsJson"><div class="grid"><label>Date<?=mk_date_widget('sale_date','','BS')?></label><label>Party<select name="party_id"><option value="">Cash Customer / None</option><?php foreach($parties as$p):?><option value="<?=$p['id']?>"><?=h($p['party_name'])?></option><?php endforeach;?></select></label><label>Customer Name<input name="customer_name" value="Cash Customer"></label><label>Phone<input name="customer_phone"></label><label>Address<input name="customer_address"></label><label>PAN<input name="customer_pan"></label><label>Payment Type<select name="payment_type"><option>Cash</option><option>Credit</option><option>Online</option><option>Cheque</option></select></label><label>Paid Now<input type="number" step=".01" min="0" name="paid_amount" value="0"></label><label>Reference<input name="payment_reference"></label><label>Bank / Wallet<input name="bank_wallet"></label><label>Discount<input type="number" step=".01" min="0" name="discount" value="0"></label><label><input type="checkbox" name="vat_enabled"> VAT</label><label>VAT Rate %<input type="number" step=".001" name="vat_rate" value="13"></label></div><hr><div class="grid"><label>Product<select id="sp"><option value="">Select</option><?php foreach($products as$p):?><option value="<?=$p['id']?>" data-rate="<?=$p['selling_price']?>" data-stock="<?=$p['stock']?>"><?=h($p['product_code'].' - '.$p['product_name'].' | Stock '.$p['stock'])?></option><?php endforeach;?></select></label><label>Qty<input id="sq" type="number" step=".001" min=".001" value="1"></label><label>Rate<input id="sr" type="number" step=".01" min="0"></label></div><div class="actions"><button type="button" onclick="addItem()">Add Item</button></div><div class="scroll"><table><thead><tr><th>Product</th><th>Qty</th><th>Rate</th><th>Total</th><th></th></tr></thead><tbody id="cart"></tbody></table></div><div class="actions"><button class="primary">Save Bill</button></div></form></div><script>let items=[];const sp=document.getElementById('sp'),sq=document.getElementById('sq'),sr=document.getElementById('sr'),cart=document.getElementById('cart'),ij=document.getElementById('itemsJson');sp.onchange=()=>sr.value=sp.selectedOptions[0]?.dataset.rate||0;function addItem(){let o=sp.selectedOptions[0],q=+sq.value,r=+sr.value;if(!sp.value||q<=0||r<0)return alert('Select product, qty and rate.');if(q>+o.dataset.stock)return alert('Insufficient stock.');items.push({product_id:+sp.value,qty:q,rate:r,name:o.textContent});draw()}function draw(){cart.innerHTML=items.map((x,i)=>`<tr><td>${x.name}</td><td>${x.qty}</td><td>${x.rate.toFixed(2)}</td><td>${(x.qty*x.rate).toFixed(2)}</td><td><button type="button" onclick="items.splice(${i},1);draw()">Remove</button></td></tr>`).join('');ij.value=JSON.stringify(items)}document.getElementById('saleForm').onsubmit=()=>{draw();return items.length?true:(alert('Add at least one item.'),false)}</script>
<?php elseif($view==='register'):?><div class="box scroll"><h3>Sales Register</h3><table><thead><tr><th>Date</th><th>Bill</th><th>Customer</th><th>Payment</th><th>Subtotal</th><th>Discount</th><th>VAT</th><th>Total</th><th>Paid</th><th>Due</th><th>Status</th></tr></thead><tbody><?php foreach($sales as$s):$tot=$s['subtotal']-$s['discount']+$s['vat_amount'];?><tr><td><?=h($s['sale_date'])?></td><td><?=h($s['bill_no'])?></td><td><?=h($s['customer_name'])?></td><td><?=h($s['payment_type'])?></td><td>Rs. <?=number_format((float)$s['subtotal'],2)?></td><td><?=number_format((float)$s['discount'],2)?></td><td><?=number_format((float)$s['vat_amount'],2)?></td><td><b>Rs. <?=number_format((float)$tot,2)?></b></td><td><?=number_format((float)$s['paid_amount'],2)?></td><td><?=number_format((float)$s['due_amount'],2)?></td><td><?=h($s['status'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($view==='reports'):$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$r=array_values(array_filter($sales,fn($s)=>$s['sale_date']>=$from&&$s['sale_date']<=$to));?><div class="box"><form method="get" class="grid"><label>From<?=mk_date_widget('from',(string)$from,'BS')?></label><label>To<?=mk_date_widget('to',(string)$to,'BS')?></label><div class="actions"><button class="primary">Show Report</button></div></form></div><div class="cards"><div class="card"><div class="label">Bills</div><div class="value"><?=count($r)?></div></div><div class="card"><div class="label">Sales Total</div><div class="value">Rs. <?=number_format(array_sum(array_map(fn($s)=>(float)$s['subtotal']-(float)$s['discount']+(float)$s['vat_amount'],$r)),2)?></div></div><div class="card"><div class="label">VAT</div><div class="value">Rs. <?=number_format(array_sum(array_column($r,'vat_amount')),2)?></div></div><div class="card"><div class="label">Due</div><div class="value">Rs. <?=number_format(array_sum(array_column($r,'due_amount')),2)?></div></div></div><div class="box scroll"><table><thead><tr><th>Date</th><th>Bill</th><th>Customer</th><th>Total</th><th>VAT</th><th>Due</th></tr></thead><tbody><?php foreach($r as$s):?><tr><td><?=h($s['sale_date'])?></td><td><?=h($s['bill_no'])?></td><td><?=h($s['customer_name'])?></td><td>Rs. <?=number_format((float)$s['subtotal']-(float)$s['discount']+(float)$s['vat_amount'],2)?></td><td><?=number_format((float)$s['vat_amount'],2)?></td><td><?=number_format((float)$s['due_amount'],2)?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($view==='stock'):?><div class="box scroll"><h3>Current Stock</h3><table><thead><tr><th>Code</th><th>Product</th><th>Unit</th><th>Purchased</th><th>Sold</th><th>Current</th><th>Avg Cost</th><th>Stock Value</th><th>Reorder</th><th>Status</th></tr></thead><tbody><?php foreach($products as$p):$pq=scalar($pdo,'SELECT COALESCE(SUM(qty*units_per_unit),0) FROM purchases WHERE business_id=? AND product_id=?',[$bid,$p['id']]);$sq=$pq-(float)$p['stock'];$cost=scalar($pdo,"SELECT COALESCE(SUM((qty*purchase_rate)-discount+CASE WHEN transport_mode='per_base' THEN transport*(qty*units_per_unit) ELSE transport END+CASE WHEN other_cost_mode='per_base' THEN other_cost*(qty*units_per_unit) ELSE other_cost END)/NULLIF(SUM(qty*units_per_unit),0),0) FROM purchases WHERE business_id=? AND product_id=?",[$bid,$p['id']]);?><tr><td><?=h($p['product_code'])?></td><td><?=h($p['product_name'])?></td><td><?=h($p['unit'])?></td><td><?=number_format($pq,3)?></td><td><?=number_format($sq,3)?></td><td><b><?=number_format((float)$p['stock'],3)?></b></td><td>Rs. <?=number_format($cost,2)?></td><td>Rs. <?=number_format($cost*(float)$p['stock'],2)?></td><td><?=number_format((float)$p['reorder_level'],2)?></td><td><?=((float)$p['reorder_level']>0&&(float)$p['stock']<=(float)$p['reorder_level'])?'⚠ Low':'OK'?></td></tr><?php endforeach;?></tbody></table></div>
<?php else:$cp=(int)($_GET['product_id']??0);?><div class="box"><form method="get"><label>Product<select name="product_id" onchange="this.form.submit()"><option value="">Select Product</option><?php foreach($products as$p):?><option value="<?=$p['id']?>" <?=$cp===$p['id']?'selected':''?>><?=h($p['product_code'].' - '.$p['product_name'])?></option><?php endforeach;?></select></label></form></div><?php if($cp):$rows=q1($pdo,"SELECT pu.*,s.supplier_name,(pu.qty*pu.units_per_unit) bq,((pu.qty*pu.purchase_rate)-pu.discount+CASE WHEN pu.transport_mode='per_base' THEN pu.transport*(pu.qty*pu.units_per_unit) ELSE pu.transport END+CASE WHEN pu.other_cost_mode='per_base' THEN pu.other_cost*(pu.qty*pu.units_per_unit) ELSE pu.other_cost END)/(pu.qty*pu.units_per_unit) actual FROM purchases pu JOIN suppliers s ON s.id=pu.supplier_id WHERE pu.business_id=? AND pu.product_id=? ORDER BY actual,pu.purchase_date DESC",[$bid,$cp]);?><div class="box scroll"><table><thead><tr><th>Date</th><th>Supplier</th><th>Purchase Qty</th><th>Base Qty</th><th>Rate</th><th>Actual / Base</th></tr></thead><tbody><?php foreach($rows as$i=>$r):?><tr><td><?=h($r['purchase_date'])?></td><td><?=h($r['supplier_name'])?><?=$i===0?' ⭐':''?></td><td><?=number_format((float)$r['qty'],3).' '.h($r['purchase_unit'])?></td><td><?=number_format((float)$r['bq'],3)?></td><td>Rs. <?=number_format((float)$r['purchase_rate'],2)?></td><td><b>Rs. <?=number_format((float)$r['actual'],2)?></b></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php endif;?></section></main><script src="https://cdn.jsdelivr.net/npm/@remotemerge/nepali-date-converter@1/dist/ndc-browser.js"></script><script src="assets/js/mero-date.js"></script><script src="assets/js/online-nav.js"></script></body></html>